<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {useUnsaved} from '../../composables/useUnsaved'
import type {components} from '@adc/contracts'
import {createProtectedClient} from '../../api/protected'
import {ApiFailure,prepareCommand,UnknownOutcomeError,type PreparedCommand} from '../../api/http'
import {useAuthenticationStore} from '../../stores/authentication'
type Cost=components['schemas']['CostView']
const api=createProtectedClient(),auth=useAuthenticationStore(),rows=ref<Cost[]>([]),next=ref<string|null>(null),busy=ref(false),unknown=ref(false),error=ref(''),notice=ref(''),confirmed=ref(false),reversal=ref<Cost|null>(null)
const form=ref({clinic_id:'',dentist_id:'',appointment_id:'',applied_treatment_id:'',cost_type:'MEDICAL_SUPPLY' as 'MEDICAL_SUPPLY'|'OPERATING',amount:'',incurred_at:'',description:'',source_reference:'',source_batch:'',verification_reference:''}),correction=ref({incurred_at:'',source_reference:'',source_batch:'',verification_reference:'',reason:''})
type Applied={applied_treatment_id:string;appointment_id:string;clinic_id:string;dentist_id:string;dentist_name:string;treatment_name:string;performed_at:string}
const applied=ref<Applied[]>([]),appliedNext=ref<string|null>(null)
let appliedVersion=0
async function loadApplied(more=false){const version=++appliedVersion;if(!more){applied.value=[];appliedNext.value=null}try{const query=new URLSearchParams({limit:'50'});if(form.value.clinic_id)query.set('clinic_id',form.value.clinic_id);if(more&&appliedNext.value)query.set('cursor',appliedNext.value);const result=await api.get<{items:Applied[];next_cursor:string|null}>('/api/v1/workspace/applied-treatments?'+query);if(version!==appliedVersion)return;applied.value=more?[...applied.value,...result.items]:result.items;appliedNext.value=result.next_cursor}catch(failure){if(version===appliedVersion)await failed(failure)}}
watch(()=>form.value.clinic_id,()=>{form.value.applied_treatment_id='';form.value.appointment_id='';confirmed.value=false;loadApplied()})
function bindApplied(){const row=applied.value.find(r=>r.applied_treatment_id===form.value.applied_treatment_id);form.value.appointment_id=row?.appointment_id??'';if(row)form.value.dentist_id=row.dentist_id;confirmed.value=false}
const clinics=ref<{id:string;label:string}[]>([]),dentists=ref<{id:string;label:string}[]>([])
async function catalogs(path:string){const all:{id:string;label:string}[]=[];let cursor:string|null=null;do{const page:{items:typeof all;next_cursor:string|null}=await api.get('/api/v1/'+path+'?limit=100'+(cursor?'&cursor='+encodeURIComponent(cursor):''));all.push(...page.items);cursor=page.next_cursor}while(cursor);return all}
const savedForm=ref(JSON.stringify(form.value))
useUnsaved(()=>JSON.stringify(form.value)!==savedForm.value||!!reversal.value&&Object.values(correction.value).some(Boolean),()=>unknown.value)
let pending:PreparedCommand|undefined
function at(value:string){return `${value.length===16?value+':00':value}+08:00`}
async function failed(failure:unknown){error.value=failure instanceof ApiFailure?({COST_SOURCE_EXISTS:'来源已存在，请核对原凭证；没有重复计入。',COST_ALREADY_REVERSED_OR_NOT_POSITIVE:'原凭证不可再次冲销。',MISSING_MEDICAL_DENTIST:'医疗用品必须明确归属实际实施牙医。'}[failure.code]??`未完成：${failure.message}`):'服务暂不可用。';if(failure instanceof ApiFailure && [401,403].includes(failure.status)){rows.value=[];reversal.value=null;applied.value=[];appliedNext.value=null;confirmed.value=false;form.value={clinic_id:'',dentist_id:'',appointment_id:'',applied_treatment_id:'',cost_type:'MEDICAL_SUPPLY',amount:'',incurred_at:'',description:'',source_reference:'',source_batch:'',verification_reference:''};savedForm.value=JSON.stringify(form.value);await auth.ensure()}}
async function load(more=false){try{const query=new URLSearchParams({limit:'50'});if(more && next.value)query.set('cursor',next.value);const page=await api.get<{items:Cost[];next_cursor:string|null}>(`/api/v1/cost-entries?${query}`);rows.value=more?[...rows.value,...page.items]:page.items;next.value=page.next_cursor}catch(failure){await failed(failure)}}
async function execute(){if(!pending)return;busy.value=true;error.value='';try{const result=await api.execute<Cost>(pending);notice.value=`凭证 ${result.data.cost_entry_id} 已确认，金额 ${result.data.amount}；原始凭证保留。`;pending=undefined;unknown.value=false;confirmed.value=false;reversal.value=null;savedForm.value=JSON.stringify(form.value);await load()}catch(failure){if(failure instanceof UnknownOutcomeError){unknown.value=true;error.value='结果尚未确认，请保留当前页面查询或重试。'}else{pending=undefined;unknown.value=false;await failed(failure)}}finally{busy.value=false}}
async function save(){if(pending || !confirmed.value)return;const input=form.value;pending=prepareCommand('recordCostEntry','POST','/api/v1/cost-entries',{...input,dentist_id:input.dentist_id||null,appointment_id:input.appointment_id||null,applied_treatment_id:input.applied_treatment_id||null,description:input.description||null,incurred_at:at(input.incurred_at)});await execute()}
async function reverse(){if(pending || !reversal.value || !confirmed.value)return;pending=prepareCommand('reverseCostEntry','POST',`/api/v1/cost-entries/${reversal.value.cost_entry_id}/reverse`,{...correction.value,incurred_at:at(correction.value.incurred_at)});await execute()}
async function query(){if(!pending)return;try{const result=await api.requestResult<{status:string}>(pending);notice.value=result.status==='SUCCEEDED'?'原请求已成功，请重新确认取回凭证。':'尚未确认成功，请保留当前页面。'}catch(failure){await failed(failure)}}
onMounted(async()=>{try{clinics.value=await catalogs('clinics');dentists.value=await catalogs('dentists')}catch(failure){await failed(failure)}await load()})
</script>
<template><section><h1>季度成本核验</h1><p>按成本实际发生时点归季。已确认凭证不可覆盖；更正先作唯一等额反号冲销，再另录正确来源。时间均为北京时间。</p><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div v-if="unknown"><button :disabled="busy" @click="query">查询办理进度</button><button :disabled="busy" @click="execute">重新确认办理结果</button></div>
<form v-if="!reversal" @submit.prevent="save"><fieldset :disabled="busy||unknown" @input="confirmed=false"><legend>核实并登记成本来源</legend><label>实际诊所<select v-model="form.clinic_id" required><option value="" disabled>选择实际诊所</option><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.label}}</option></select></label><label>成本归属<select v-model="form.dentist_id" :disabled="!!form.applied_treatment_id" :required="form.cost_type==='MEDICAL_SUPPLY'"><option value="">公共运营费用</option><option v-for="d in dentists" :key="d.id" :value="d.id">{{d.label}}</option></select><small>公共运营费用留空；医疗用品归实际实施者。</small></label><label>成本类型<select v-model="form.cost_type"><option value="MEDICAL_SUPPLY">医疗用品</option><option value="OPERATING">运营费用</option></select></label><label>成本金额<input v-model="form.amount" required inputmode="decimal" pattern="[0-9]{1,12}\.[0-9]{2}" placeholder="100.00"></label><label>经核验发生时间<input v-model="form.incurred_at" type="datetime-local" step="1" required></label><label>原始来源编号<input v-model="form.source_reference" maxlength="100" required></label><label>来源批次<input v-model="form.source_batch" maxlength="60" required></label><label>来源核验依据<input v-model="form.verification_reference" maxlength="255" required></label><label class="wide">关联实际治疗（可选）<select v-model="form.applied_treatment_id" :disabled="!form.clinic_id" @change="bindApplied"><option value="">不关联具体治疗</option><option v-for="row in applied" :key="row.applied_treatment_id" :value="row.applied_treatment_id">{{row.treatment_name}} · {{row.dentist_name}} · {{new Date(row.performed_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</option></select><small>选择后按实际实施者归属；诊所及牙医仍由服务端核验。</small></label><button v-if="appliedNext" type="button" @click="loadApplied(true)">加载更多实际治疗</button><label class="wide">说明／零成本已核实范围<textarea v-model="form.description" :required="/^0+\.00$/.test(form.amount)" maxlength="180" placeholder="零额须说明已确认的具体范围；系统同时保留诊所、季度及类型。"></textarea></label></fieldset><div class="confirmation-summary"><h3>保存前核对</h3><p>{{clinics.find(c=>c.id===form.clinic_id)?.label||'尚未选择诊所'}} · {{dentists.find(d=>d.id===form.dentist_id)?.label||'公共运营费用'}}</p><p>{{form.cost_type==='MEDICAL_SUPPLY'?'医疗用品':'运营费用'}} · 金额 {{form.amount||'尚未填写'}} · {{form.incurred_at||'尚未填写发生日期'}}</p><p>原始来源 {{form.source_reference||'尚未填写'}}</p></div><label><input v-model="confirmed" type="checkbox" :disabled="busy||unknown" required>已核实来源、发生时点及归属，确认保存不可覆盖的凭证</label><button :disabled="busy||unknown||!confirmed">确认成本凭证</button></form>
<section v-else><h2>冲销凭证 {{reversal.cost_entry_id}}</h2><p>原金额 {{reversal.amount}}；预计冲销 {{reversal.amount.startsWith('-')?reversal.amount.slice(1):'-'+reversal.amount}}；反号金额、类型及归属由服务端生成。冲销按本次核实发生时间归季。</p><form @submit.prevent="reverse"><fieldset :disabled="busy||unknown" @input="confirmed=false"><label>冲销实际发生时间<input v-model="correction.incurred_at" type="datetime-local" step="1" required></label><label>冲销新来源编号<input v-model="correction.source_reference" required maxlength="100"></label><label>冲销来源批次<input v-model="correction.source_batch" required maxlength="60"></label><label>冲销核验依据<input v-model="correction.verification_reference" required maxlength="255"></label><label>冲销原因<input v-model="correction.reason" required maxlength="255"></label></fieldset><label><input v-model="confirmed" type="checkbox" required :disabled="busy||unknown">已独立核实本次冲销凭证</label><button :disabled="busy||unknown||!confirmed">生成唯一等额反号冲销</button><button type="button" :disabled="busy||unknown" @click="reversal=null;confirmed=false">返回凭证列表</button></form></section>
<h2>已确认来源</h2><button :disabled="busy||unknown" @click="load()">刷新成本凭证</button><div class="table-scroll"><table><thead><tr><th>凭证／来源</th><th>诊所／牙医</th><th>类型</th><th>发生时间</th><th>金额</th><th>确认主体</th><th>冲销原引用</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.cost_entry_id"><td>{{row.cost_entry_id}}<br>{{row.source_reference}}</td><td>{{clinics.find(c=>c.id===row.clinic_id)?.label??row.clinic_id}} / {{dentists.find(d=>d.id===row.dentist_id)?.label??'公共'}}</td><td>{{row.cost_type==='MEDICAL_SUPPLY'?'医疗用品':'运营费用'}}</td><td>{{new Date(row.incurred_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</td><td>{{row.amount}}</td><td>{{row.confirmed_by}}</td><td>{{row.reversal_of_id??'—'}}</td><td><button v-if="!row.reversal_of_id && !/^0+\.00$/.test(row.amount)" :disabled="busy||unknown" @click="reversal=row;confirmed=false">核验冲销</button></td></tr></tbody></table></div><p v-if="!rows.length&&!error" class="empty-state">暂无已确认成本来源，可核实来源后登记。</p><button v-if="next" :disabled="busy||unknown" @click="load(true)">更多成本凭证</button></section></template>
<style scoped>fieldset{display:flex;gap:16px;flex-wrap:wrap;padding:20px;margin:20px 0}label{display:grid;gap:6px;min-width:180px}label:has([type=checkbox]){display:flex;margin:12px 0}input,select,textarea{padding:9px;border:1px solid #bacdc5;border-radius:5px}.wide{flex:1 1 100%}button{padding:9px 14px;margin:4px}small{max-width:250px;color:#53675e}table{font-size:13px}</style>
